// Minimal CDP driver using Node's built-in WebSocket + fetch.
const BASE = 'http://127.0.0.1:9222';

async function newTab(url) {
  const res = await fetch(`${BASE}/json/new?${encodeURIComponent(url)}`, { method: 'PUT' });
  return res.json();
}

function connect(wsUrl) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(wsUrl);
    ws.addEventListener('open', () => resolve(ws));
    ws.addEventListener('error', reject);
  });
}

function send(ws, method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = Math.floor(Math.random() * 1e9);
    const handler = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.id === id) {
        ws.removeEventListener('message', handler);
        if (msg.error) reject(new Error(JSON.stringify(msg.error)));
        else resolve(msg.result);
      }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id, method, params }));
  });
}

function waitEvent(ws, eventName, timeoutMs = 10000) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      ws.removeEventListener('message', handler);
      reject(new Error(`timeout waiting for ${eventName}`));
    }, timeoutMs);
    const handler = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.method === eventName) {
        clearTimeout(timer);
        ws.removeEventListener('message', handler);
        resolve(msg.params);
      }
    };
    ws.addEventListener('message', handler);
  });
}

async function evaluate(ws, expression) {
  const result = await send(ws, 'Runtime.evaluate', {
    expression,
    returnByValue: true,
    awaitPromise: true,
  });
  if (result.exceptionDetails) {
    throw new Error(JSON.stringify(result.exceptionDetails));
  }
  return result.result.value;
}

export async function withPage(url, fn) {
  const tab = await newTab('about:blank');
  const ws = await connect(tab.webSocketDebuggerUrl);
  await send(ws, 'Page.enable');
  await send(ws, 'Runtime.enable');
  await send(ws, 'Network.enable');

  const loaded = waitEvent(ws, 'Page.loadEventFired', 20000);
  await send(ws, 'Page.navigate', { url });
  await loaded;

  try {
    await fn({ ws, evaluate: (expr) => evaluate(ws, expr), send: (m, p) => send(ws, m, p) });
  } finally {
    await fetch(`${BASE}/json/close/${tab.id}`);
  }
}

export async function screenshot(ws, path) {
  const fs = await import('node:fs/promises');
  const result = await send(ws, 'Page.captureScreenshot', { format: 'png' });
  await fs.writeFile(path, Buffer.from(result.data, 'base64'));
}

