import { withPage, screenshot } from '/tmp/cdp.mjs';

await withPage('http://localhost:4200/?date=2026-09-15', async ({ ws, evaluate }) => {
  await new Promise((r) => setTimeout(r, 1500));
  const cardCount = await evaluate(`document.querySelectorAll('[data-testid="movie-card"]').length`);
  console.log('movie cards:', cardCount);
  const firstCard = await evaluate(`
    (() => {
      const card = document.querySelector('[data-testid="movie-card"]');
      if (!card) return null;
      return {
        title: card.querySelector('[data-testid="movie-title"]')?.textContent,
        genre: card.querySelector('[data-testid="movie-genre"]')?.textContent,
        runtime: card.querySelector('[data-testid="movie-runtime"]')?.textContent,
        format: card.querySelector('[data-testid="movie-format"]')?.textContent,
        screenings: [...card.querySelectorAll('[data-testid="screening-button"]')].map(b => b.textContent),
      };
    })()
  `);
  console.log('first card:', firstCard);
  await screenshot(ws, '/tmp/shot2.png');

  // click first screening button
  const screeningId = await evaluate(`
    document.querySelector('[data-testid="screening-button"]').getAttribute('data-screening-id')
  `);
  console.log('clicking screening id', screeningId);
  await evaluate(`document.querySelector('[data-testid="screening-button"]').click()`);
  await new Promise((r) => setTimeout(r, 1000));
  const url = await evaluate('location.pathname');
  console.log('url after click:', url);
  const seatMapTitle = await evaluate(`document.querySelector('[data-testid="seat-map-title"]')?.textContent`);
  console.log('seat map title:', seatMapTitle);
  const subtitle = await evaluate(`document.querySelector('[data-testid="seat-map-subtitle"]')?.textContent`);
  console.log('subtitle:', subtitle);
  const seatCount = await evaluate(`document.querySelectorAll('[data-testid="seat"]').length`);
  const couchCount = await evaluate(`document.querySelectorAll('[data-testid="couch"]').length`);
  console.log('seats:', seatCount, 'couches:', couchCount);
  await screenshot(ws, '/tmp/shot3.png');
});

