import { withPage } from '/tmp/cdp.mjs';

await withPage('http://localhost:4200/screenings/1/seats', async ({ ws, evaluate, send }) => {
  const events = [];
  ws.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.method && msg.method.startsWith('Network.')) {
      if (msg.method === 'Network.requestWillBeSent') {
        events.push(`REQ ${msg.params.request.method} ${msg.params.request.url}`);
      }
      if (msg.method === 'Network.responseReceived') {
        events.push(`RES ${msg.params.response.status} ${msg.params.response.url}`);
      }
      if (msg.method === 'Network.loadingFailed') {
        events.push(`FAIL ${msg.params.errorText} ${msg.params.type}`);
      }
    }
    if (msg.method === 'Runtime.exceptionThrown') {
      events.push('EXC ' + JSON.stringify(msg.params.exceptionDetails.exception?.description || msg.params.exceptionDetails.text));
    }
    if (msg.method === 'Runtime.consoleAPICalled') {
      events.push('CONSOLE ' + msg.params.type + ' ' + msg.params.args.map(a => a.value ?? a.description).join(' '));
    }
  });
  await new Promise((r) => setTimeout(r, 2500));
  console.log(events.filter(e => e.includes('3000') || e.startsWith('EXC') || e.startsWith('CONSOLE')).join('\n'));
});

