const BASE = 'http://127.0.0.1:9222';
async function newTab(url) {
  const res = await fetch(BASE + '/json/new?' + encodeURIComponent(url), { method: 'PUT' });
  return res.json();
}
function connect(wsUrl) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(wsUrl);
    ws.addEventListener('open', () => resolve(ws));
    ws.addEventListener('error', reject);
  });
}
function send(ws, method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = Math.floor(Math.random() * 1e9);
    const handler = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.id === id) {
        ws.removeEventListener('message', handler);
        if (msg.error) reject(new Error(JSON.stringify(msg.error)));
        else resolve(msg.result);
      }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id, method, params }));
  });
}
function evaluate(ws, expression) {
  return send(ws, 'Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }).then(r =>
    r.exceptionDetails ? 'EXC:' + JSON.stringify(r.exceptionDetails) : r.result?.value
  );
}
async function screenshot(ws, path) {
  const fs = await import('node:fs/promises');
  const result = await send(ws, 'Page.captureScreenshot', { format: 'png' });
  await fs.writeFile(path, Buffer.from(result.data, 'base64'));
}
function waitLoad(ws) {
  return new Promise((r) => {
    const h = (e) => { const m = JSON.parse(e.data); if (m.method === 'Page.loadEventFired') { ws.removeEventListener('message', h); r(); } };
    ws.addEventListener('message', h);
  });
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const tab = await newTab('about:blank');
  const ws = await connect(tab.webSocketDebuggerUrl);
  const consoleErrors = [];
  ws.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.method === 'Runtime.consoleAPICalled' && (msg.params.type === 'error' || msg.params.type === 'warning')) {
      consoleErrors.push(msg.params.args.map((a) => a.value ?? a.description).join(' '));
    }
    if (msg.method === 'Runtime.exceptionThrown') {
      consoleErrors.push('EXC ' + JSON.stringify(msg.params.exceptionDetails.exception?.description));
    }
  });
  await send(ws, 'Page.enable');
  await send(ws, 'Runtime.enable');

  // 1. Movie list with screenings date
  let l = waitLoad(ws);
  await send(ws, 'Page.navigate', { url: 'http://localhost:4200/?date=2026-09-15' });
  await l;
  await sleep(1500);
  console.log('=== Movie list ===');
  console.log('day-buttons:', await evaluate(ws, `document.querySelectorAll('[data-testid=day-button]').length`));
  console.log('movie-cards:', await evaluate(ws, `document.querySelectorAll('[data-testid=movie-card]').length`));
  console.log('screening-buttons:', await evaluate(ws, `document.querySelectorAll('[data-testid=screening-button]').length`));
  await screenshot(ws, '/tmp/g1-movielist.png');

  // 2. Click first screening button
  await evaluate(ws, `document.querySelectorAll('[data-testid=screening-button]')[0].click()`);
  await sleep(1500);
  console.log('=== Seat map ===');
  console.log('path:', await evaluate(ws, 'location.pathname'));
  console.log('title:', await evaluate(ws, `document.querySelector('[data-testid=seat-map-title]')?.textContent`));
  console.log('subtitle:', await evaluate(ws, `document.querySelector('[data-testid=seat-map-subtitle]')?.textContent`));
  console.log('seat count:', await evaluate(ws, `document.querySelectorAll('[data-testid=seat]').length`));
  console.log('couch count:', await evaluate(ws, `document.querySelectorAll('[data-testid=couch]').length`));
  console.log('aisle count:', await evaluate(ws, `document.querySelectorAll('[data-testid=aisle]').length`));
  console.log('row count:', await evaluate(ws, `document.querySelectorAll('[data-testid=seat-row]').length`));
  console.log('accessible count:', await evaluate(ws, `document.querySelectorAll('[data-state=accessible]').length`));
  console.log('legend items:', await evaluate(ws, `Array.from(document.querySelectorAll('[data-testid=legend-item]')).map(e => e.dataset.state + ':' + e.textContent).join(', ')`));

  // select: one accessible seat (row1 col10), one regular seat (row6 col8), one couch (row15 pair 1-2)
  const accSeat = await evaluate(ws, `document.querySelector('[data-testid=seat][data-row="1"][data-column="10"]')`);
  await evaluate(ws, `document.querySelector('[data-testid=seat][data-row="1"][data-column="10"]').click()`);
  await evaluate(ws, `document.querySelector('[data-testid=seat][data-row="6"][data-column="8"]').click()`);
  await evaluate(ws, `document.querySelector('[data-testid=couch][data-row="15"][data-column-start="1"]').click()`);
  await sleep(300);
  console.log('selected count text:', await evaluate(ws, `document.querySelector('[data-testid=selected-seats-count]')?.textContent`));
  console.log('selected rows:', await evaluate(ws, `Array.from(document.querySelectorAll('[data-testid=selected-seats-row]')).map(e => e.textContent).join(' | ')`));
  await screenshot(ws, '/tmp/g2-seatmap.png');

  // 3. Continue to summary
  await evaluate(ws, `document.querySelector('[data-testid=continue-button]').click()`);
  await sleep(1000);
  console.log('=== Summary ===');
  console.log('path:', await evaluate(ws, 'location.pathname'));
  console.log('title:', await evaluate(ws, `document.querySelector('[data-testid=summary-title]')?.textContent`));
  console.log('item count:', await evaluate(ws, `document.querySelectorAll('[data-testid=summary-item]').length`));
  console.log('total:', await evaluate(ws, `document.querySelector('[data-testid=summary-total]')?.textContent`));
  await screenshot(ws, '/tmp/g3-summary.png');

  // 4. Confirm to checkout
  await evaluate(ws, `document.querySelector('[data-testid=confirm-button]').click()`);
  await sleep(1000);
  console.log('=== Checkout ===');
  console.log('path:', await evaluate(ws, 'location.pathname'));
  console.log('title:', await evaluate(ws, `document.querySelector('[data-testid=checkout-title]')?.textContent`));

  // Try submitting empty form first to check validation
  await evaluate(ws, `document.querySelector('[data-testid=pay-button]').click()`);
  await sleep(500);
  console.log('firstName-error on empty submit:', await evaluate(ws, `document.querySelector('[data-testid=firstName-error]')?.textContent`));

  // fill valid data
  async function setVal(testid, value) {
    await evaluate(ws, `(() => {
      const el = document.querySelector('[data-testid=${testid}]');
      const proto = Object.getPrototypeOf(el);
      const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
      setter.call(el, ${JSON.stringify(value)});
      el.dispatchEvent(new Event('input', { bubbles: true }));
    })()`);
  }
  await setVal('firstName-input', 'Jane');
  await setVal('lastName-input', 'Doe');
  await setVal('email-input', 'jane@example.com');
  await setVal('confirmEmail-input', 'jane@example.com');
  await setVal('phone-input', '123456789');
  await evaluate(ws, `document.querySelector('[data-testid=terms-input]').click()`);
  await sleep(300);
  console.log('pay-button text:', await evaluate(ws, `document.querySelector('[data-testid=pay-button]')?.textContent`));
  await screenshot(ws, '/tmp/g4-checkout.png');

  await evaluate(ws, `document.querySelector('[data-testid=pay-button]').click()`);
  await sleep(1500);
  console.log('=== Confirmation ===');
  console.log('path:', await evaluate(ws, 'location.pathname'));
  console.log('heading:', await evaluate(ws, `document.querySelector('[data-testid=confirmation-heading]')?.textContent`));
  console.log('message:', await evaluate(ws, `document.querySelector('[data-testid=confirmation-message]')?.textContent`));
  await screenshot(ws, '/tmp/g5-confirmation.png');

  console.log('=== Console errors/warnings/exceptions captured ===');
  console.log(consoleErrors.join('\n') || '(none)');

  await fetch(BASE + '/json/close/' + tab.id);
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

