const BASE = 'http://127.0.0.1:9222';
async function newTab(url) {
  const res = await fetch(BASE + '/json/new?' + encodeURIComponent(url), { method: 'PUT' });
  return res.json();
}
function connect(wsUrl) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(wsUrl);
    ws.addEventListener('open', () => resolve(ws));
    ws.addEventListener('error', reject);
  });
}
function send(ws, method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = Math.floor(Math.random() * 1e9);
    const handler = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.id === id) { ws.removeEventListener('message', handler); if (msg.error) reject(new Error(JSON.stringify(msg.error))); else resolve(msg.result); }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id, method, params }));
  });
}
function evaluate(ws, expression) {
  return send(ws, 'Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }).then(r => r.exceptionDetails ? 'EXC:' + JSON.stringify(r.exceptionDetails) : r.result?.value);
}
function waitLoad(ws) { return new Promise(r => { const h = (e) => { const m = JSON.parse(e.data); if (m.method === 'Page.loadEventFired') { ws.removeEventListener('message', h); r(); } }; ws.addEventListener('message', h); }); }
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
